import { useState } from "react";
import { Box, Typography, Paper, Tabs, Tab, Chip, IconButton, Slider, Switch, FormControlLabel } from "@mui/material";
import PlayArrowIcon from "@mui/icons-material/PlayArrow";
import PauseIcon from "@mui/icons-material/Pause";
import ViewModuleIcon from "@mui/icons-material/ViewModule";
import ViewStreamIcon from "@mui/icons-material/ViewStream";
import TimelineIcon from "@mui/icons-material/Timeline";

// REVOLUTIONARY NEW DESIGN - Timeline + Split Screen + Interactive
const ForecastPageRevolutionary = () => {
    const [activeView, setActiveView] = useState<"timeline" | "split" | "flow">("timeline");
    const [selectedDay, setSelectedDay] = useState(3);
    const [isPlaying, setIsPlaying] = useState(false);
    const [showComparison, setShowComparison] = useState(false);

    // Sample data
    const forecastData = [
        { day: 0, date: "Mon", stockpile: 34580, weather: "Sunny", temp: 22, impact: "low", accuracy: 96 },
        { day: 1, date: "Tue", stockpile: 35200, weather: "Cloudy", temp: 20, impact: "low", accuracy: 95 },
        { day: 2, date: "Wed", stockpile: 34900, weather: "Rain", temp: 18, impact: "high", accuracy: 92 },
        { day: 3, date: "Thu", stockpile: 36100, weather: "Sunny", temp: 23, impact: "low", accuracy: 97 },
        { day: 4, date: "Fri", stockpile: 36800, weather: "Cloudy", temp: 21, impact: "medium", accuracy: 94 },
        { day: 5, date: "Sat", stockpile: 37200, weather: "Sunny", temp: 24, impact: "low", accuracy: 96 },
        { day: 6, date: "Sun", stockpile: 36500, weather: "Rain", temp: 19, impact: "high", accuracy: 91 },
    ];

    const currentData = forecastData[selectedDay];

    return (
        <Box sx={{ height: "calc(100vh - 120px)", display: "flex", flexDirection: "column" }}>
            {/* CONTROL BAR - Horizontal timeline controls */}
            <Paper
                elevation={0}
                sx={{
                    p: 2,
                    mb: 2,
                    bgcolor: "#003DA5",
                    color: "white",
                    borderRadius: 3,
                    display: "flex",
                    alignItems: "center",
                    gap: 3,
                }}
            >
                <Box>
                    <Typography variant="overline" sx={{ opacity: 0.8, fontSize: "0.7rem" }}>
                        FORECAST SIMULATION
                    </Typography>
                    <Typography variant="h5" fontWeight={700}>
                        7-Day Timeline View
                    </Typography>
                </Box>

                <Box sx={{ flex: 1, display: "flex", alignItems: "center", gap: 2 }}>
                    <IconButton
                        sx={{ bgcolor: "rgba(255,255,255,0.2)", color: "white" }}
                        onClick={() => setIsPlaying(!isPlaying)}
                    >
                        {isPlaying ? <PauseIcon /> : <PlayArrowIcon />}
                    </IconButton>

                    <Box sx={{ flex: 1 }}>
                        <Slider
                            value={selectedDay}
                            onChange={(_, value) => setSelectedDay(value as number)}
                            min={0}
                            max={6}
                            marks={forecastData.map((d) => ({ value: d.day, label: d.date }))}
                            sx={{
                                color: "#FFD100",
                                "& .MuiSlider-markLabel": {
                                    color: "white",
                                    fontSize: "0.75rem",
                                    fontWeight: 600,
                                },
                                "& .MuiSlider-mark": {
                                    bgcolor: "rgba(255,255,255,0.3)",
                                },
                            }}
                        />
                    </Box>
                </Box>

                <Box display="flex" gap={1}>
                    <IconButton
                        sx={{
                            bgcolor: activeView === "timeline" ? "#FFD100" : "rgba(255,255,255,0.2)",
                            color: activeView === "timeline" ? "#003DA5" : "white",
                        }}
                        onClick={() => setActiveView("timeline")}
                    >
                        <TimelineIcon />
                    </IconButton>
                    <IconButton
                        sx={{
                            bgcolor: activeView === "split" ? "#FFD100" : "rgba(255,255,255,0.2)",
                            color: activeView === "split" ? "#003DA5" : "white",
                        }}
                        onClick={() => setActiveView("split")}
                    >
                        <ViewStreamIcon />
                    </IconButton>
                    <IconButton
                        sx={{
                            bgcolor: activeView === "flow" ? "#FFD100" : "rgba(255,255,255,0.2)",
                            color: activeView === "flow" ? "#003DA5" : "white",
                        }}
                        onClick={() => setActiveView("flow")}
                    >
                        <ViewModuleIcon />
                    </IconButton>
                </Box>
            </Paper>

            {/* MAIN CONTENT AREA - Changes based on view */}
            <Box sx={{ flex: 1, display: "flex", gap: 2, overflow: "hidden" }}>
                {/* TIMELINE VIEW - Vertical timeline with data flowing */}
                {activeView === "timeline" && (
                    <>
                        {/* LEFT: Data Point Focus */}
                        <Box
                            sx={{
                                flex: "0 0 400px",
                                bgcolor: "white",
                                borderRadius: 3,
                                p: 4,
                                display: "flex",
                                flexDirection: "column",
                                justifyContent: "center",
                            }}
                        >
                            <Typography variant="overline" color="text.secondary" gutterBottom>
                                {currentData.date.toUpperCase()} - DAY {currentData.day + 1}
                            </Typography>

                            <Typography variant="h1" fontWeight={800} color="#003DA5" sx={{ mb: 1 }}>
                                {currentData.stockpile.toLocaleString()}
                            </Typography>

                            <Typography variant="h6" color="text.secondary" gutterBottom>
                                Kilotonnes Coal Stockpile
                            </Typography>

                            <Box sx={{ my: 4, p: 3, bgcolor: "#F8F9FA", borderRadius: 2 }}>
                                <Box display="flex" justifyContent="space-between" mb={2}>
                                    <Typography variant="body2" color="text.secondary">
                                        Weather
                                    </Typography>
                                    <Chip label={currentData.weather} size="small" />
                                </Box>
                                <Box display="flex" justifyContent="space-between" mb={2}>
                                    <Typography variant="body2" color="text.secondary">
                                        Temperature
                                    </Typography>
                                    <Typography variant="body1" fontWeight={700}>
                                        {currentData.temp}°C
                                    </Typography>
                                </Box>
                                <Box display="flex" justifyContent="space-between" mb={2}>
                                    <Typography variant="body2" color="text.secondary">
                                        Impact Level
                                    </Typography>
                                    <Chip
                                        label={currentData.impact.toUpperCase()}
                                        size="small"
                                        color={currentData.impact === "high" ? "error" : currentData.impact === "medium" ? "warning" : "success"}
                                    />
                                </Box>
                                <Box display="flex" justifyContent="space-between">
                                    <Typography variant="body2" color="text.secondary">
                                        Forecast Accuracy
                                    </Typography>
                                    <Typography variant="body1" fontWeight={700} color="#4CAF50">
                                        {currentData.accuracy}%
                                    </Typography>
                                </Box>
                            </Box>

                            <FormControlLabel
                                control={<Switch checked={showComparison} onChange={(e) => setShowComparison(e.target.checked)} />}
                                label="Show Historical Comparison"
                            />
                        </Box>

                        {/* RIGHT: Visual Flow */}
                        <Box sx={{ flex: 1, bgcolor: "white", borderRadius: 3, p: 3, position: "relative", overflow: "hidden" }}>
                            {/* Vertical Timeline */}
                            <Box
                                sx={{
                                    position: "absolute",
                                    left: "50%",
                                    top: 0,
                                    bottom: 0,
                                    width: "4px",
                                    bgcolor: "#E0E0E0",
                                    transform: "translateX(-50%)",
                                }}
                            />

                            {/* Timeline Points */}
                            <Box sx={{ display: "flex", flexDirection: "column", gap: 3, position: "relative" }}>
                                {forecastData.map((data, index) => {
                                    const isActive = index === selectedDay;
                                    const isPast = index < selectedDay;

                                    return (
                                        <Box
                                            key={data.day}
                                            sx={{
                                                display: "flex",
                                                alignItems: "center",
                                                opacity: isActive ? 1 : isPast ? 0.6 : 0.4,
                                                transition: "all 0.3s ease",
                                                cursor: "pointer",
                                                "&:hover": { opacity: 1 },
                                            }}
                                            onClick={() => setSelectedDay(index)}
                                        >
                                            {/* Left side - Date */}
                                            <Box sx={{ flex: "0 0 45%", textAlign: "right", pr: 4 }}>
                                                <Typography variant="h6" fontWeight={700}>
                                                    {data.date}
                                                </Typography>
                                                <Typography variant="body2" color="text.secondary">
                                                    Day {data.day + 1}
                                                </Typography>
                                            </Box>

                                            {/* Center dot */}
                                            <Box
                                                sx={{
                                                    width: isActive ? 24 : 16,
                                                    height: isActive ? 24 : 16,
                                                    borderRadius: "50%",
                                                    bgcolor: isActive ? "#FFD100" : isPast ? "#003DA5" : "#E0E0E0",
                                                    border: isActive ? "4px solid #003DA5" : "none",
                                                    zIndex: 1,
                                                    transition: "all 0.3s ease",
                                                }}
                                            />

                                            {/* Right side - Value */}
                                            <Box sx={{ flex: "0 0 45%", pl: 4 }}>
                                                <Typography variant="h5" fontWeight={700} color="#003DA5">
                                                    {data.stockpile.toLocaleString()}
                                                </Typography>
                                                <Box display="flex" gap={1} mt={0.5}>
                                                    <Chip label={data.weather} size="small" sx={{ fontSize: "0.7rem" }} />
                                                    <Chip
                                                        label={`${data.accuracy}%`}
                                                        size="small"
                                                        color="success"
                                                        sx={{ fontSize: "0.7rem" }}
                                                    />
                                                </Box>
                                            </Box>
                                        </Box>
                                    );
                                })}
                            </Box>
                        </Box>
                    </>
                )}

                {/* SPLIT VIEW - Side by side comparison */}
                {activeView === "split" && (
                    <>
                        {/* Left Half - Chart/Visual */}
                        <Box
                            sx={{
                                flex: 1,
                                bgcolor: "white",
                                borderRadius: 3,
                                p: 3,
                                display: "flex",
                                flexDirection: "column",
                            }}
                        >
                            <Typography variant="h6" fontWeight={700} gutterBottom>
                                Forecast Trend
                            </Typography>
                            <Box
                                sx={{
                                    flex: 1,
                                    display: "flex",
                                    alignItems: "flex-end",
                                    justifyContent: "space-around",
                                    gap: 1,
                                    mt: 2,
                                }}
                            >
                                {forecastData.map((data, index) => {
                                    const isActive = index === selectedDay;
                                    const height = (data.stockpile / 40000) * 100;

                                    return (
                                        <Box
                                            key={data.day}
                                            sx={{
                                                flex: 1,
                                                display: "flex",
                                                flexDirection: "column",
                                                alignItems: "center",
                                                cursor: "pointer",
                                            }}
                                            onClick={() => setSelectedDay(index)}
                                        >
                                            <Box
                                                sx={{
                                                    width: "100%",
                                                    height: `${height}%`,
                                                    bgcolor: isActive ? "#FFD100" : "#003DA5",
                                                    borderRadius: "8px 8px 0 0",
                                                    transition: "all 0.3s ease",
                                                    "&:hover": {
                                                        bgcolor: "#FFD100",
                                                        transform: "scaleY(1.05)",
                                                    },
                                                    position: "relative",
                                                }}
                                            >
                                                {isActive && (
                                                    <Typography
                                                        variant="caption"
                                                        fontWeight={700}
                                                        sx={{
                                                            position: "absolute",
                                                            top: -25,
                                                            left: "50%",
                                                            transform: "translateX(-50%)",
                                                            whiteSpace: "nowrap",
                                                        }}
                                                    >
                                                        {data.stockpile.toLocaleString()}
                                                    </Typography>
                                                )}
                                            </Box>
                                            <Typography variant="caption" fontWeight={700} sx={{ mt: 1 }}>
                                                {data.date}
                                            </Typography>
                                        </Box>
                                    );
                                })}
                            </Box>
                        </Box>

                        {/* Right Half - Data Grid */}
                        <Box
                            sx={{
                                flex: 1,
                                bgcolor: "white",
                                borderRadius: 3,
                                p: 3,
                                display: "flex",
                                flexDirection: "column",
                                gap: 2,
                            }}
                        >
                            <Typography variant="h6" fontWeight={700} gutterBottom>
                                Detailed Breakdown
                            </Typography>
                            {forecastData.map((data, index) => {
                                const isActive = index === selectedDay;
                                return (
                                    <Paper
                                        key={data.day}
                                        elevation={isActive ? 4 : 0}
                                        sx={{
                                            p: 2,
                                            bgcolor: isActive ? "#003DA5" : "#F8F9FA",
                                            color: isActive ? "white" : "inherit",
                                            cursor: "pointer",
                                            transition: "all 0.2s ease",
                                            border: isActive ? "2px solid #FFD100" : "1px solid transparent",
                                        }}
                                        onClick={() => setSelectedDay(index)}
                                    >
                                        <Box display="flex" justifyContent="space-between" alignItems="center">
                                            <Box>
                                                <Typography variant="body2" sx={{ opacity: isActive ? 0.9 : 0.7 }}>
                                                    {data.date} - Day {data.day + 1}
                                                </Typography>
                                                <Typography variant="h6" fontWeight={700}>
                                                    {data.stockpile.toLocaleString()} Kt
                                                </Typography>
                                            </Box>
                                            <Box textAlign="right">
                                                <Chip
                                                    label={data.weather}
                                                    size="small"
                                                    sx={{
                                                        bgcolor: isActive ? "rgba(255,255,255,0.2)" : "white",
                                                        color: isActive ? "white" : "#003DA5",
                                                    }}
                                                />
                                                <Typography variant="caption" display="block" sx={{ mt: 0.5, opacity: 0.8 }}>
                                                    {data.accuracy}% accuracy
                                                </Typography>
                                            </Box>
                                        </Box>
                                    </Paper>
                                );
                            })}
                        </Box>
                    </>
                )}

                {/* FLOW VIEW - Circular/Radial layout */}
                {activeView === "flow" && (
                    <Box
                        sx={{
                            flex: 1,
                            bgcolor: "white",
                            borderRadius: 3,
                            p: 3,
                            display: "flex",
                            flexDirection: "column",
                            alignItems: "center",
                            justifyContent: "center",
                        }}
                    >
                        <Typography variant="h6" fontWeight={700} gutterBottom>
                            Circular Flow View
                        </Typography>
                        <Typography variant="body2" color="text.secondary" gutterBottom sx={{ mb: 4 }}>
                            Interactive circular timeline - Click on any segment
                        </Typography>

                        {/* Circular Layout */}
                        <Box sx={{ position: "relative", width: 500, height: 500 }}>
                            {/* Center Display */}
                            <Box
                                sx={{
                                    position: "absolute",
                                    top: "50%",
                                    left: "50%",
                                    transform: "translate(-50%, -50%)",
                                    textAlign: "center",
                                    zIndex: 10,
                                }}
                            >
                                <Typography variant="h2" fontWeight={800} color="#003DA5">
                                    {currentData.stockpile.toLocaleString()}
                                </Typography>
                                <Typography variant="body1" color="text.secondary">
                                    Kilotonnes
                                </Typography>
                                <Typography variant="h6" fontWeight={700} sx={{ mt: 2 }}>
                                    {currentData.date}
                                </Typography>
                                <Chip label={currentData.weather} sx={{ mt: 1 }} />
                            </Box>

                            {/* Circular Points */}
                            {forecastData.map((data, index) => {
                                const angle = (index / forecastData.length) * 2 * Math.PI - Math.PI / 2;
                                const radius = 200;
                                const x = 250 + radius * Math.cos(angle);
                                const y = 250 + radius * Math.sin(angle);
                                const isActive = index === selectedDay;

                                return (
                                    <Box
                                        key={data.day}
                                        sx={{
                                            position: "absolute",
                                            left: x,
                                            top: y,
                                            transform: "translate(-50%, -50%)",
                                            cursor: "pointer",
                                        }}
                                        onClick={() => setSelectedDay(index)}
                                    >
                                        <Box
                                            sx={{
                                                width: isActive ? 80 : 60,
                                                height: isActive ? 80 : 60,
                                                borderRadius: "50%",
                                                bgcolor: isActive ? "#FFD100" : "#003DA5",
                                                display: "flex",
                                                flexDirection: "column",
                                                alignItems: "center",
                                                justifyContent: "center",
                                                transition: "all 0.3s ease",
                                                border: isActive ? "4px solid #003DA5" : "none",
                                                "&:hover": {
                                                    transform: "scale(1.1)",
                                                },
                                            }}
                                        >
                                            <Typography
                                                variant="caption"
                                                fontWeight={700}
                                                color={isActive ? "#003DA5" : "white"}
                                            >
                                                {data.date}
                                            </Typography>
                                            <Typography
                                                variant="caption"
                                                fontWeight={700}
                                                color={isActive ? "#003DA5" : "white"}
                                                sx={{ fontSize: "0.65rem" }}
                                            >
                                                {(data.stockpile / 1000).toFixed(1)}K
                                            </Typography>
                                        </Box>
                                    </Box>
                                );
                            })}
                        </Box>
                    </Box>
                )}
            </Box>
        </Box>
    );
};

export default ForecastPageRevolutionary;
